import java.util.List;
import java.util.stream.Collectors;

public class TagJoiner {
    public static String joinTags(List<String> tags) {
        return tags.stream()
                .map(t -> t.trim().toLowerCase())
                .distinct()
                .sorted()
                .collect(Collectors.joining(","));
    }
}

